insert into public.topics (slug, title, description, language, level, position, pair_key, content)
values
  ('greetings', 'Greetings', 'Aprende a saludar en situaciones cotidianas en inglés.', 'EN', 'BEGINNER', 1, 'greetings', $topic${"sections":[{"title":"Saludos básicos","intro":"Estos son los saludos más comunes en inglés. Fíjate en cuán formal o informal suena cada uno.","vocabulary":[{"term":"Hi","translation":"Hola (informal)"},{"term":"Hello","translation":"Hola (neutro)"},{"term":"Good morning","translation":"Buenos días"},{"term":"Good afternoon","translation":"Buenas tardes"},{"term":"Good evening","translation":"Buenas noches (al llegar)"}],"dialogue":[{"speaker":"A","text":"Hi, how are you?"},{"speaker":"B","text":"I'm good, thanks. And you?"},{"speaker":"A","text":"Pretty good."}],"practicePhrases":["Hi, how are you?","Good morning, nice to see you.","I'm doing well, thank you."]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Saluda a alguien y pregúntale cómo está. Usa los saludos que aprendiste."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('saludos', 'Saludos', 'Learn how to greet people in everyday Spanish situations.', 'ES', 'BEGINNER', 1, 'greetings', $topic${"sections":[{"title":"Basic greetings","intro":"These are the most common ways to greet someone in Spanish. Pay attention to how casual or formal each one feels.","vocabulary":[{"term":"Hola","translation":"Hi"},{"term":"Buenos días","translation":"Good morning"},{"term":"Buenas tardes","translation":"Good afternoon"},{"term":"¿Cómo estás?","translation":"How are you? (informal)"},{"term":"¿Cómo está usted?","translation":"How are you? (formal)"}],"dialogue":[{"speaker":"A","text":"¡Hola! ¿Cómo estás?"},{"speaker":"B","text":"Bien, gracias. ¿Y tú?"},{"speaker":"A","text":"Muy bien también."}],"practicePhrases":["Hola, ¿cómo estás?","Buenos días.","Estoy bien, gracias."]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Greet someone and ask how they are. Use the greetings you learned."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('introductions', 'Introductions', 'Preséntate en inglés: nombre, origen y algo sobre ti.', 'EN', 'BEGINNER', 2, 'introductions', $topic${"sections":[{"title":"Presentándote","intro":"Después de saludar, lo normal es decir tu nombre y algo sobre ti.","vocabulary":[{"term":"My name is...","translation":"Me llamo..."},{"term":"I'm from...","translation":"Soy de..."},{"term":"Nice to meet you","translation":"Encantado/a de conocerte"},{"term":"What about you?","translation":"¿Y tú?"}],"dialogue":[{"speaker":"A","text":"Hi, my name is Sarah."},{"speaker":"B","text":"Nice to meet you, Sarah. I'm Diego."},{"speaker":"A","text":"Where are you from?"},{"speaker":"B","text":"I'm from Madrid. What about you?"}],"practicePhrases":["Hi, my name is [your name].","I'm from [your city].","Nice to meet you."]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Preséntate a un extraño en 30 segundos. Di tu nombre, de dónde eres y algo breve sobre ti."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('presentaciones', 'Presentaciones', 'Introduce yourself in Spanish: name, origin, a little about you.', 'ES', 'BEGINNER', 2, 'introductions', $topic${"sections":[{"title":"Introducing yourself","intro":"How to say your name, where you're from, and what you do.","vocabulary":[{"term":"Me llamo...","translation":"My name is..."},{"term":"Soy de...","translation":"I'm from..."},{"term":"Mucho gusto","translation":"Nice to meet you"},{"term":"¿Y tú?","translation":"And you?"}],"dialogue":[{"speaker":"A","text":"Hola, me llamo Sara."},{"speaker":"B","text":"Mucho gusto, Sara. Yo soy Diego."},{"speaker":"A","text":"¿De dónde eres?"},{"speaker":"B","text":"Soy de Madrid. ¿Y tú?"}],"practicePhrases":["Hola, me llamo [tu nombre].","Soy de [tu ciudad].","Mucho gusto."]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Introduce yourself to a stranger in 30 seconds. Say your name, where you are from, and something brief about you."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('numbers-and-prices', 'Numbers and Prices', 'Cuenta, di precios y paga cosas en inglés del día a día.', 'EN', 'BEGINNER', 5, 'numbers-and-prices', $topic${"sections":[{"title":"Los números","intro":"Números que usas cada día: para contar, dar tu teléfono o decir cuántos. Di cada uno en voz alta.","vocabulary":[{"term":"one, two, three","translation":"uno, dos, tres"},{"term":"four, five, six","translation":"cuatro, cinco, seis"},{"term":"seven, eight, nine, ten","translation":"siete, ocho, nueve, diez"},{"term":"eleven","translation":"once"},{"term":"twelve","translation":"doce"},{"term":"twenty","translation":"veinte"},{"term":"thirty","translation":"treinta"},{"term":"a hundred","translation":"cien"}],"dialogue":[{"speaker":"A","text":"How many tickets do you need?"},{"speaker":"B","text":"Two, please. One for me and one for my friend."},{"speaker":"A","text":"That's twelve euros."}],"practicePhrases":["Two coffees, please.","My number is six, one, five…","I need three tickets."]},{"title":"Precios y pagar","intro":"Pregunta cuánto cuesta algo, entiende el precio y paga. Aparece siempre que vas de compras.","vocabulary":[{"term":"How much is it?","translation":"¿Cuánto cuesta?"},{"term":"How much is this?","translation":"¿Cuánto vale esto?"},{"term":"expensive / cheap","translation":"caro / barato"},{"term":"cash","translation":"efectivo"},{"term":"card","translation":"tarjeta"},{"term":"the change","translation":"el cambio (vuelta)"},{"term":"the receipt","translation":"el recibo"}],"dialogue":[{"speaker":"A","text":"How much is this T-shirt?"},{"speaker":"B","text":"It's fifteen euros."},{"speaker":"A","text":"OK, I’ll take it. Can I pay by card?"},{"speaker":"B","text":"Of course. Here’s your receipt."}],"practicePhrases":["How much is it?","Can I pay by card?","That's too expensive.","Here you are."]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Imagina que compras algo en una tienda. Pregunta cuánto cuesta, di el precio en voz alta y decide si lo pagas con tarjeta o en efectivo."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('numeros-y-precios', 'Los números y los precios', 'Count, say prices and pay for things in everyday Spanish.', 'ES', 'BEGINNER', 5, 'numbers-and-prices', $topic${"sections":[{"title":"Numbers","intro":"Numbers you use every day: to count, give your phone number, or say how many. Say each one out loud.","vocabulary":[{"term":"uno, dos, tres","translation":"one, two, three"},{"term":"cuatro, cinco, seis","translation":"four, five, six"},{"term":"siete, ocho, nueve, diez","translation":"seven, eight, nine, ten"},{"term":"once","translation":"eleven"},{"term":"doce","translation":"twelve"},{"term":"veinte","translation":"twenty"},{"term":"treinta","translation":"thirty"},{"term":"cien","translation":"a hundred"}],"dialogue":[{"speaker":"A","text":"¿Cuántas entradas necesitas?"},{"speaker":"B","text":"Dos, por favor. Una para mí y otra para mi amigo."},{"speaker":"A","text":"Son doce euros."}],"practicePhrases":["Dos cafés, por favor.","Mi número es seis, uno, cinco…","Necesito tres entradas."]},{"title":"Prices and paying","intro":"Ask how much something costs, understand the price, and pay. These come up every single time you shop.","vocabulary":[{"term":"¿Cuánto cuesta?","translation":"How much is it?"},{"term":"¿Cuánto vale esto?","translation":"How much is this?"},{"term":"caro / barato","translation":"expensive / cheap"},{"term":"efectivo","translation":"cash"},{"term":"tarjeta","translation":"card"},{"term":"el cambio (la vuelta)","translation":"the change"},{"term":"el recibo","translation":"the receipt"}],"dialogue":[{"speaker":"A","text":"¿Cuánto cuesta esta camiseta?"},{"speaker":"B","text":"Son quince euros."},{"speaker":"A","text":"Vale, me la llevo. ¿Puedo pagar con tarjeta?"},{"speaker":"B","text":"Claro. Aquí tienes el recibo."}],"practicePhrases":["¿Cuánto cuesta?","¿Puedo pagar con tarjeta?","Es demasiado caro.","Aquí tienes."]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Imagine you're buying something at a shop. Ask how much it costs, say the price out loud, and decide whether to pay by card or cash."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('telling-the-time', 'Telling the Time', 'Pregunta y di la hora en inglés del día a día.', 'EN', 'BEGINNER', 6, 'telling-the-time', $topic${"sections":[{"title":"La hora","intro":"Cómo preguntar la hora y decirla. La necesitas para citas, autobuses y horarios.","vocabulary":[{"term":"What time is it?","translation":"¿Qué hora es?"},{"term":"It's three o'clock","translation":"Son las tres (en punto)"},{"term":"half past four","translation":"las cuatro y media"},{"term":"quarter past five","translation":"las cinco y cuarto"},{"term":"quarter to six","translation":"las seis menos cuarto"},{"term":"in the morning / afternoon","translation":"por la mañana / tarde"},{"term":"noon / midnight","translation":"mediodía / medianoche"}],"dialogue":[{"speaker":"A","text":"Excuse me, what time is it?"},{"speaker":"B","text":"It's quarter past ten."},{"speaker":"A","text":"Thanks. What time does the shop open?"},{"speaker":"B","text":"At half past ten."}],"practicePhrases":["What time is it?","It's half past two.","See you at eight."]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Pregunta la hora y queda con alguien: di a qué hora os veis y dónde."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('la-hora', '¿Qué hora es?', 'Ask and tell the time in everyday Spanish.', 'ES', 'BEGINNER', 6, 'telling-the-time', $topic${"sections":[{"title":"Telling the time","intro":"How to ask for the time and say it. You need this for meetings, buses and opening hours.","vocabulary":[{"term":"¿Qué hora es?","translation":"What time is it?"},{"term":"Son las tres (en punto)","translation":"It's three o'clock"},{"term":"las cuatro y media","translation":"half past four"},{"term":"las cinco y cuarto","translation":"quarter past five"},{"term":"las seis menos cuarto","translation":"quarter to six"},{"term":"por la mañana / tarde","translation":"in the morning / afternoon"},{"term":"mediodía / medianoche","translation":"noon / midnight"}],"dialogue":[{"speaker":"A","text":"Perdona, ¿qué hora es?"},{"speaker":"B","text":"Son las diez y cuarto."},{"speaker":"A","text":"Gracias. ¿A qué hora abre la tienda?"},{"speaker":"B","text":"A las diez y media."}],"practicePhrases":["¿Qué hora es?","Son las dos y media.","Nos vemos a las ocho."]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Ask the time and make plans with someone: say what time you'll meet and where."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('family-and-people', 'Family and People', 'Habla de tu familia y de la gente que te rodea, en inglés.', 'EN', 'BEGINNER', 7, 'family-and-people', $topic${"sections":[{"title":"La familia","intro":"Las personas más cercanas. Perfecto para romper el hielo cuando conoces a alguien.","vocabulary":[{"term":"mother / father","translation":"madre / padre"},{"term":"parents","translation":"padres"},{"term":"sister / brother","translation":"hermana / hermano"},{"term":"son / daughter","translation":"hijo / hija"},{"term":"wife / husband","translation":"esposa / esposo (marido)"},{"term":"friend","translation":"amigo / amiga"},{"term":"children / kids","translation":"hijos / niños"}],"dialogue":[{"speaker":"A","text":"Do you have any brothers or sisters?"},{"speaker":"B","text":"Yes, I have one sister. And you?"},{"speaker":"A","text":"I have two brothers."},{"speaker":"B","text":"Nice. Are they older or younger?"}],"practicePhrases":["This is my sister.","I have two kids.","Do you have any brothers or sisters?"]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Presenta a tu familia: di quiénes son y algo de cada uno (nombre, edad o dónde viven)."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('la-familia', 'La familia', 'Talk about your family and the people around you, in Spanish.', 'ES', 'BEGINNER', 7, 'family-and-people', $topic${"sections":[{"title":"Family","intro":"The people closest to you. Great for small talk when you meet someone new.","vocabulary":[{"term":"madre / padre","translation":"mother / father"},{"term":"los padres","translation":"parents"},{"term":"hermana / hermano","translation":"sister / brother"},{"term":"hijo / hija","translation":"son / daughter"},{"term":"esposa / esposo (marido)","translation":"wife / husband"},{"term":"amigo / amiga","translation":"friend"},{"term":"los hijos / los niños","translation":"children / kids"}],"dialogue":[{"speaker":"A","text":"¿Tienes hermanos?"},{"speaker":"B","text":"Sí, tengo una hermana. ¿Y tú?"},{"speaker":"A","text":"Tengo dos hermanos."},{"speaker":"B","text":"Qué bien. ¿Son mayores o menores?"}],"practicePhrases":["Esta es mi hermana.","Tengo dos hijos.","¿Tienes hermanos?"]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Introduce your family: say who they are and something about each one (name, age, or where they live)."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('directions', 'Directions', 'Pregunta y da indicaciones sencillas por la calle, en inglés.', 'EN', 'BEGINNER', 8, 'directions', $topic${"sections":[{"title":"Cómo llegar","intro":"Pregunta dónde está algo y sigue indicaciones sencillas. Esencial cuando te pierdes.","vocabulary":[{"term":"Where is…?","translation":"¿Dónde está…?"},{"term":"How do I get to…?","translation":"¿Cómo llego a…?"},{"term":"straight ahead","translation":"todo recto"},{"term":"turn left / right","translation":"gira a la izquierda / derecha"},{"term":"next to / near","translation":"al lado de / cerca de"},{"term":"on the corner","translation":"en la esquina"},{"term":"it's far / close","translation":"está lejos / cerca"}],"dialogue":[{"speaker":"A","text":"Excuse me, how do I get to the station?"},{"speaker":"B","text":"Go straight ahead and turn left. It’s next to the bank."},{"speaker":"A","text":"Is it far?"},{"speaker":"B","text":"No, it’s close. Five minutes."}],"practicePhrases":["Where is the bathroom?","How do I get to the center?","Turn right at the corner."]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Alguien te pregunta cómo llegar a un sitio. Dale indicaciones: recto, giros y alguna referencia."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('como-llegar', 'Cómo llegar', 'Ask for and give simple directions on the street, in Spanish.', 'ES', 'BEGINNER', 8, 'directions', $topic${"sections":[{"title":"Getting there","intro":"Ask where something is and follow simple directions. Essential when you get lost.","vocabulary":[{"term":"¿Dónde está…?","translation":"Where is…?"},{"term":"¿Cómo llego a…?","translation":"How do I get to…?"},{"term":"todo recto","translation":"straight ahead"},{"term":"gira a la izquierda / derecha","translation":"turn left / right"},{"term":"al lado de / cerca de","translation":"next to / near"},{"term":"en la esquina","translation":"on the corner"},{"term":"está lejos / cerca","translation":"it's far / close"}],"dialogue":[{"speaker":"A","text":"Perdona, ¿cómo llego a la estación?"},{"speaker":"B","text":"Ve todo recto y gira a la izquierda. Está al lado del banco."},{"speaker":"A","text":"¿Está lejos?"},{"speaker":"B","text":"No, está cerca. Cinco minutos."}],"practicePhrases":["¿Dónde está el baño?","¿Cómo llego al centro?","Gira a la derecha en la esquina."]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Someone asks you how to get somewhere. Give directions: straight ahead, turns, and a landmark."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('daily-routine', 'Daily Routine', 'Describe tu día típico con verbos del día a día, en inglés.', 'EN', 'BEGINNER', 9, 'daily-routine', $topic${"sections":[{"title":"La rutina diaria","intro":"Los verbos para describir un día normal. Perfecto para practicar el presente.","vocabulary":[{"term":"wake up / get up","translation":"despertarse / levantarse"},{"term":"have breakfast","translation":"desayunar"},{"term":"go to work","translation":"ir al trabajo"},{"term":"have lunch","translation":"comer / almorzar"},{"term":"come home","translation":"volver a casa"},{"term":"have dinner","translation":"cenar"},{"term":"go to bed","translation":"acostarse"},{"term":"every day","translation":"todos los días"}],"dialogue":[{"speaker":"A","text":"What time do you get up?"},{"speaker":"B","text":"I get up at seven. Then I have breakfast and go to work."},{"speaker":"A","text":"And what do you do in the evening?"},{"speaker":"B","text":"I have dinner and go to bed early."}],"practicePhrases":["I get up at seven.","I go to work by bus.","I go to bed late."]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Cuenta tu día normal de principio a fin: a qué hora te levantas, qué haces y cuándo te acuestas."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('la-rutina-diaria', 'La rutina diaria', 'Describe your typical day with everyday verbs, in Spanish.', 'ES', 'BEGINNER', 9, 'daily-routine', $topic${"sections":[{"title":"Daily routine","intro":"The verbs you use to describe an ordinary day. Perfect for practising the present tense.","vocabulary":[{"term":"despertarse / levantarse","translation":"wake up / get up"},{"term":"desayunar","translation":"have breakfast"},{"term":"ir al trabajo","translation":"go to work"},{"term":"comer / almorzar","translation":"have lunch"},{"term":"volver a casa","translation":"come home"},{"term":"cenar","translation":"have dinner"},{"term":"acostarse","translation":"go to bed"},{"term":"todos los días","translation":"every day"}],"dialogue":[{"speaker":"A","text":"¿A qué hora te levantas?"},{"speaker":"B","text":"Me levanto a las siete. Luego desayuno y voy al trabajo."},{"speaker":"A","text":"¿Y qué haces por la noche?"},{"speaker":"B","text":"Ceno y me acuesto temprano."}],"practicePhrases":["Me levanto a las siete.","Voy al trabajo en autobús.","Me acuesto tarde."]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Describe your normal day from start to finish: what time you get up, what you do, and when you go to bed."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('getting-a-table', 'Getting a Table', 'Entra en un restaurante, menciona si tienes reserva y consigue mesa, en inglés.', 'EN', 'INTERMEDIATE', 10, 'getting-a-table', $topic${"sections":[{"title":"Conseguir una mesa","intro":"Lo que necesitas para entrar y sentarte.","vocabulary":[{"term":"A table for two, please","translation":"Una mesa para dos, por favor"},{"term":"Do you have a reservation?","translation":"¿Tienen reserva?"},{"term":"Inside or outside?","translation":"¿Adentro o afuera?"}],"dialogue":[{"speaker":"Host","text":"Hi there! Do you have a reservation?"},{"speaker":"Guest","text":"No, we don't. Do you have a table for two?"},{"speaker":"Host","text":"Sure, follow me. Inside or outside?"},{"speaker":"Guest","text":"Outside, please."}],"practicePhrases":["A table for two, please.","We don't have a reservation.","Outside, please."]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Entras a un restaurante con un amigo. Saluda al host, di si tienes reserva, pide una mesa y elige dónde sentarte."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('conseguir-mesa', 'Conseguir una mesa', 'Walk into a restaurant in Spanish: reservation, table, where to sit.', 'ES', 'INTERMEDIATE', 10, 'getting-a-table', $topic${"sections":[{"title":"Getting a table","intro":"These phrases will help you walk into a restaurant and get seated.","vocabulary":[{"term":"Una mesa para dos, por favor","translation":"A table for two, please"},{"term":"¿Tienen reserva?","translation":"Do you have a reservation?"},{"term":"Adentro o en la terraza","translation":"Inside or on the terrace"}],"dialogue":[{"speaker":"Anfitrión","text":"¡Hola! ¿Tienen reserva?"},{"speaker":"Cliente","text":"No, no tenemos. ¿Hay mesa para dos?"},{"speaker":"Anfitrión","text":"Sí, claro. ¿Adentro o en la terraza?"},{"speaker":"Cliente","text":"En la terraza, por favor."}],"practicePhrases":["Una mesa para dos, por favor.","No tenemos reserva.","En la terraza, por favor."]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"You walk into a restaurant with a friend. Greet the host, say whether you have a reservation, ask for a table, and choose where to sit."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('ordering-food', 'Ordering Food', 'Pide el menú, ordena con educación y paga la cuenta en inglés.', 'EN', 'INTERMEDIATE', 11, 'ordering-food', $topic${"sections":[{"title":"Pedir comida","intro":"Cómo pedir educadamente.","vocabulary":[{"term":"I'll have...","translation":"Tomaré..."},{"term":"Could I get...?","translation":"¿Podría pedir...?"},{"term":"What do you recommend?","translation":"¿Qué recomienda?"},{"term":"The bill, please","translation":"La cuenta, por favor"}],"dialogue":[{"speaker":"Server","text":"Are you ready to order?"},{"speaker":"Guest","text":"Yes. What do you recommend?"},{"speaker":"Server","text":"The grilled salmon is excellent."},{"speaker":"Guest","text":"Great, I'll have that. And a glass of water, please."}],"practicePhrases":["Could I get the menu, please?","I'll have the [dish name].","The bill, please."]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"El camarero llega a tu mesa. Pídele recomendaciones, ordena un plato y una bebida, y al final pide la cuenta."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('pedir-comida', 'Pedir comida', 'Order in Spanish: menu, dish, drink, and the bill.', 'ES', 'INTERMEDIATE', 11, 'ordering-food', $topic${"sections":[{"title":"Ordering food","intro":"How to ask for what you want — politely.","vocabulary":[{"term":"Voy a pedir...","translation":"I'll have..."},{"term":"¿Qué me recomienda?","translation":"What do you recommend?"},{"term":"La cuenta, por favor","translation":"The bill, please"}],"dialogue":[{"speaker":"Camarero","text":"¿Listos para pedir?"},{"speaker":"Cliente","text":"Sí. ¿Qué me recomienda?"},{"speaker":"Camarero","text":"El salmón a la parrilla está muy bueno."},{"speaker":"Cliente","text":"Perfecto, voy a pedirlo. Y un vaso de agua, por favor."}],"practicePhrases":["¿Me trae el menú, por favor?","Voy a pedir el [plato].","La cuenta, por favor."]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"The waiter comes to your table. Ask for recommendations, order a dish and a drink, and ask for the bill at the end."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('at-the-airport', 'At the Airport', 'Factura, pasa el control y embarca tu vuelo en inglés.', 'EN', 'INTERMEDIATE', 20, 'at-the-airport', $topic${"sections":[{"title":"En el aeropuerto","intro":"Las palabras y frases que necesitas desde la facturación hasta la puerta. Las usas cada vez que vuelas.","vocabulary":[{"term":"boarding pass","translation":"tarjeta de embarque"},{"term":"check-in desk","translation":"mostrador de facturación"},{"term":"luggage / baggage","translation":"equipaje"},{"term":"carry-on","translation":"equipaje de mano"},{"term":"gate","translation":"puerta (de embarque)"},{"term":"delayed / on time","translation":"retrasado / a tiempo"},{"term":"passport","translation":"pasaporte"},{"term":"security","translation":"control de seguridad"}],"dialogue":[{"speaker":"A","text":"Good morning. Where are you flying today?"},{"speaker":"B","text":"To Madrid. Here's my passport."},{"speaker":"A","text":"Are you checking any bags?"},{"speaker":"B","text":"Just this one. Can I take my backpack as carry-on?"},{"speaker":"A","text":"Of course. Your gate is B12 and boarding starts at 10:30."}],"practicePhrases":["Where's the check-in desk?","Is the flight on time?","I'd like a window seat, please.","Which gate does it leave from?"]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Estás facturando para un vuelo. Da tu destino, di cuántas maletas llevas y pregunta por la puerta de embarque."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('en-el-aeropuerto', 'En el aeropuerto', 'Check in, pass security and board your flight in Spanish.', 'ES', 'INTERMEDIATE', 20, 'at-the-airport', $topic${"sections":[{"title":"At the airport","intro":"The words and phrases you need from check-in to the gate. You use these every time you fly.","vocabulary":[{"term":"la tarjeta de embarque","translation":"boarding pass"},{"term":"el mostrador de facturación","translation":"check-in desk"},{"term":"el equipaje","translation":"luggage / baggage"},{"term":"el equipaje de mano","translation":"carry-on"},{"term":"la puerta (de embarque)","translation":"gate"},{"term":"retrasado / a tiempo","translation":"delayed / on time"},{"term":"el pasaporte","translation":"passport"},{"term":"el control de seguridad","translation":"security"}],"dialogue":[{"speaker":"A","text":"Buenos días. ¿A dónde vuela hoy?"},{"speaker":"B","text":"A Madrid. Aquí tiene mi pasaporte."},{"speaker":"A","text":"¿Factura alguna maleta?"},{"speaker":"B","text":"Solo esta. ¿Puedo llevar la mochila como equipaje de mano?"},{"speaker":"A","text":"Claro. Su puerta es la B12 y el embarque empieza a las 10:30."}],"practicePhrases":["¿Dónde está el mostrador de facturación?","¿El vuelo va a tiempo?","Quería un asiento de ventana, por favor.","¿De qué puerta sale?"]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"You're checking in for a flight. Give your destination, say how many bags you have, and ask about your gate."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('at-work', 'At Work', 'Habla de tu trabajo, reuniones y plazos en inglés.', 'EN', 'INTERMEDIATE', 21, 'at-work', $topic${"sections":[{"title":"En el trabajo","intro":"Cómo hablar de tu jornada: pedir ayuda, organizar horarios y gestionar plazos.","vocabulary":[{"term":"meeting","translation":"reunión"},{"term":"deadline","translation":"fecha límite / plazo"},{"term":"email","translation":"correo"},{"term":"colleague / coworker","translation":"compañero de trabajo"},{"term":"boss / manager","translation":"jefe / jefa"},{"term":"to be busy","translation":"estar ocupado"},{"term":"task / project","translation":"tarea / proyecto"},{"term":"day off","translation":"día libre"}],"dialogue":[{"speaker":"A","text":"Do you have a minute? I need help with the report."},{"speaker":"B","text":"Sure, but I'm a bit busy. Can we talk after the meeting?"},{"speaker":"A","text":"No problem. When's the deadline?"},{"speaker":"B","text":"Friday. Let's meet at 3 and finish it together."}],"practicePhrases":["I have a meeting at ten.","Can you send me the email?","I'm working on it.","I'll take a day off tomorrow."]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Habla de tu trabajo: qué haces, con quién trabajas y qué tienes pendiente esta semana."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('en-el-trabajo', 'En el trabajo', 'Talk about your job, meetings and deadlines in Spanish.', 'ES', 'INTERMEDIATE', 21, 'at-work', $topic${"sections":[{"title":"At work","intro":"How to talk about your work day: asking for help, scheduling, and handling deadlines.","vocabulary":[{"term":"la reunión","translation":"meeting"},{"term":"la fecha límite / el plazo","translation":"deadline"},{"term":"el correo","translation":"email"},{"term":"el compañero de trabajo","translation":"colleague / coworker"},{"term":"el jefe / la jefa","translation":"boss / manager"},{"term":"estar ocupado/a","translation":"to be busy"},{"term":"la tarea / el proyecto","translation":"task / project"},{"term":"el día libre","translation":"day off"}],"dialogue":[{"speaker":"A","text":"¿Tienes un minuto? Necesito ayuda con el informe."},{"speaker":"B","text":"Claro, pero estoy un poco ocupado. ¿Hablamos después de la reunión?"},{"speaker":"A","text":"Sin problema. ¿Cuándo es la fecha límite?"},{"speaker":"B","text":"El viernes. Quedamos a las 3 y lo terminamos juntos."}],"practicePhrases":["Tengo una reunión a las diez.","¿Me puedes enviar el correo?","Estoy en ello.","Mañana me tomo un día libre."]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Talk about your job: what you do, who you work with, and what you have to finish this week."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('at-the-doctor', 'At the Doctor', 'Describe síntomas y entiende al médico en inglés.', 'EN', 'INTERMEDIATE', 22, 'at-the-doctor', $topic${"sections":[{"title":"En el médico","intro":"Explicar cómo te sientes y qué te duele. Importante saberlo antes de necesitarlo fuera.","vocabulary":[{"term":"it hurts","translation":"me duele"},{"term":"headache","translation":"dolor de cabeza"},{"term":"fever","translation":"fiebre"},{"term":"cough","translation":"tos"},{"term":"prescription","translation":"receta"},{"term":"pain / painful","translation":"dolor / doloroso"},{"term":"to feel sick","translation":"sentirse mal"},{"term":"appointment","translation":"cita"}],"dialogue":[{"speaker":"A","text":"What's the matter?"},{"speaker":"B","text":"I don't feel well. I have a headache and a bit of a fever."},{"speaker":"A","text":"How long have you felt like this?"},{"speaker":"B","text":"Since yesterday. And I have a cough too."},{"speaker":"A","text":"Okay. I'll give you a prescription. Rest and drink water."}],"practicePhrases":["I have an appointment at four.","My throat hurts.","I need to see a doctor.","How often should I take it?"]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Estás en el médico. Explica cómo te sientes, qué te duele y desde cuándo."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('en-el-medico', 'En el médico', 'Describe symptoms and understand a doctor in Spanish.', 'ES', 'INTERMEDIATE', 22, 'at-the-doctor', $topic${"sections":[{"title":"At the doctor","intro":"Explaining how you feel and what hurts. Important to know before you need it abroad.","vocabulary":[{"term":"me duele","translation":"it hurts"},{"term":"el dolor de cabeza","translation":"headache"},{"term":"la fiebre","translation":"fever"},{"term":"la tos","translation":"cough"},{"term":"la receta","translation":"prescription"},{"term":"el dolor","translation":"pain"},{"term":"sentirse mal","translation":"to feel sick"},{"term":"la cita","translation":"appointment"}],"dialogue":[{"speaker":"A","text":"¿Qué le pasa?"},{"speaker":"B","text":"No me siento bien. Tengo dolor de cabeza y un poco de fiebre."},{"speaker":"A","text":"¿Desde cuándo se siente así?"},{"speaker":"B","text":"Desde ayer. Y también tengo tos."},{"speaker":"A","text":"De acuerdo. Le doy una receta. Descanse y beba agua."}],"practicePhrases":["Tengo cita a las cuatro.","Me duele la garganta.","Necesito ver a un médico.","¿Cada cuánto debo tomarlo?"]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"You're at the doctor. Explain how you feel, what hurts, and since when."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('making-plans', 'Making Plans', 'Invita, propón y organiza planes con la gente en inglés.', 'EN', 'INTERMEDIATE', 23, 'making-plans', $topic${"sections":[{"title":"Hacer planes","intro":"Proponer cosas que hacer, ponerse de acuerdo en una hora y decir que no con educación.","vocabulary":[{"term":"Are you free?","translation":"¿estás libre?"},{"term":"to meet up","translation":"quedar"},{"term":"How about…?","translation":"¿qué tal…?"},{"term":"it sounds good","translation":"suena bien"},{"term":"I can't make it","translation":"no puedo ir"},{"term":"maybe / perhaps","translation":"quizás"},{"term":"let's…","translation":"vamos a…"},{"term":"to be late / early","translation":"llegar tarde / temprano"}],"dialogue":[{"speaker":"A","text":"Are you free this weekend?"},{"speaker":"B","text":"I think so. What did you have in mind?"},{"speaker":"A","text":"How about dinner on Saturday?"},{"speaker":"B","text":"Sounds good! What time?"},{"speaker":"A","text":"Around eight. Let's meet at the restaurant."}],"practicePhrases":["Do you want to come?","I can't make it on Friday.","Let's meet at seven.","Maybe another day."]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Invita a alguien a hacer algo el fin de semana: propón una actividad, un día y una hora."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('hacer-planes', 'Hacer planes', 'Invite, suggest and arrange plans with people in Spanish.', 'ES', 'INTERMEDIATE', 23, 'making-plans', $topic${"sections":[{"title":"Making plans","intro":"Suggesting things to do, agreeing on a time, and saying no politely.","vocabulary":[{"term":"¿estás libre?","translation":"are you free?"},{"term":"quedar","translation":"to meet up"},{"term":"¿qué tal…?","translation":"how about…?"},{"term":"suena bien","translation":"it sounds good"},{"term":"no puedo ir","translation":"I can't make it"},{"term":"quizás","translation":"maybe / perhaps"},{"term":"vamos a…","translation":"let's…"},{"term":"llegar tarde / temprano","translation":"to be late / early"}],"dialogue":[{"speaker":"A","text":"¿Estás libre este fin de semana?"},{"speaker":"B","text":"Creo que sí. ¿Qué tenías en mente?"},{"speaker":"A","text":"¿Qué tal cenar el sábado?"},{"speaker":"B","text":"¡Suena bien! ¿A qué hora?"},{"speaker":"A","text":"Sobre las ocho. Quedamos en el restaurante."}],"practicePhrases":["¿Quieres venir?","No puedo el viernes.","Quedamos a las siete.","Quizás otro día."]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Invite someone to do something this weekend: suggest an activity, a day, and a time."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('at-the-hotel', 'At the Hotel', 'Haz el check-in y pregunta por tu habitación en inglés.', 'EN', 'INTERMEDIATE', 24, 'at-the-hotel', $topic${"sections":[{"title":"En el hotel","intro":"Desde llegar con una reserva hasta preguntar por el desayuno y la salida.","vocabulary":[{"term":"reservation / booking","translation":"reserva"},{"term":"single / double room","translation":"habitación individual / doble"},{"term":"key / key card","translation":"llave / tarjeta"},{"term":"check-in / check-out","translation":"entrada / salida"},{"term":"breakfast included","translation":"desayuno incluido"},{"term":"Wi-Fi password","translation":"contraseña del wifi"},{"term":"towel","translation":"toalla"},{"term":"front desk / reception","translation":"recepción"}],"dialogue":[{"speaker":"A","text":"Hi, I have a reservation under García."},{"speaker":"B","text":"Welcome. A double room for two nights, right?"},{"speaker":"A","text":"That's right. Is breakfast included?"},{"speaker":"B","text":"Yes, from 7 to 10. Here's your key card. Room 305."},{"speaker":"A","text":"Great. What's the Wi-Fi password?"}],"practicePhrases":["I have a reservation.","What time is check-out?","Could I have an extra towel?","Is breakfast included?"]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Llegas a un hotel. Di que tienes una reserva, pregunta por el desayuno y la hora de salida."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('en-el-hotel', 'En el hotel', 'Check in, ask about your room and amenities in Spanish.', 'ES', 'INTERMEDIATE', 24, 'at-the-hotel', $topic${"sections":[{"title":"At the hotel","intro":"Everything from arriving with a booking to asking about breakfast and check-out.","vocabulary":[{"term":"la reserva","translation":"reservation / booking"},{"term":"la habitación individual / doble","translation":"single / double room"},{"term":"la llave / la tarjeta","translation":"key / key card"},{"term":"la entrada / la salida","translation":"check-in / check-out"},{"term":"el desayuno incluido","translation":"breakfast included"},{"term":"la contraseña del wifi","translation":"Wi-Fi password"},{"term":"la toalla","translation":"towel"},{"term":"la recepción","translation":"front desk / reception"}],"dialogue":[{"speaker":"A","text":"Hola, tengo una reserva a nombre de García."},{"speaker":"B","text":"Bienvenido. Una habitación doble para dos noches, ¿verdad?"},{"speaker":"A","text":"Así es. ¿El desayuno está incluido?"},{"speaker":"B","text":"Sí, de 7 a 10. Aquí tiene su tarjeta. Habitación 305."},{"speaker":"A","text":"Genial. ¿Cuál es la contraseña del wifi?"}],"practicePhrases":["Tengo una reserva.","¿A qué hora es la salida?","¿Me puede dar una toalla más?","¿El desayuno está incluido?"]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"You arrive at a hotel. Say you have a reservation, and ask about breakfast and check-out time."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('shopping-and-returns', 'Shopping and Returns', 'Compra ropa, pruébatela y devuélvela en inglés.', 'EN', 'INTERMEDIATE', 25, 'shopping-and-returns', $topic${"sections":[{"title":"De compras","intro":"Tallas, probadores y cómo devolver o cambiar algo que no te queda bien.","vocabulary":[{"term":"size","translation":"talla"},{"term":"to try on","translation":"probarse"},{"term":"fitting room","translation":"probador"},{"term":"receipt","translation":"recibo / ticket"},{"term":"to return / exchange","translation":"devolver / cambiar"},{"term":"it doesn't fit","translation":"no me queda bien"},{"term":"on sale / discount","translation":"en oferta / descuento"},{"term":"Can I help you?","translation":"¿te ayudo?"}],"dialogue":[{"speaker":"A","text":"Hi, can I help you?"},{"speaker":"B","text":"Yes, can I try these on? What size is this?"},{"speaker":"A","text":"It’s a medium. The fitting rooms are over there."},{"speaker":"B","text":"Thanks. Actually, it doesn’t fit. Can I exchange it for a large?"},{"speaker":"A","text":"Of course. Do you have the receipt?"}],"practicePhrases":["Can I try this on?","Do you have it in a smaller size?","I'd like to return this.","Is this on sale?"]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Estás en una tienda de ropa. Pregunta por una talla, di que te la quieres probar y que quieres devolver algo."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('de-compras', 'De compras', 'Buy clothes, try things on and return them in Spanish.', 'ES', 'INTERMEDIATE', 25, 'shopping-and-returns', $topic${"sections":[{"title":"Shopping","intro":"Sizes, fitting rooms, and how to return or exchange something that doesn’t fit.","vocabulary":[{"term":"la talla","translation":"size"},{"term":"probarse","translation":"to try on"},{"term":"el probador","translation":"fitting room"},{"term":"el recibo / el ticket","translation":"receipt"},{"term":"devolver / cambiar","translation":"to return / exchange"},{"term":"no me queda bien","translation":"it doesn't fit"},{"term":"en oferta / con descuento","translation":"on sale / discount"},{"term":"¿te ayudo?","translation":"Can I help you?"}],"dialogue":[{"speaker":"A","text":"Hola, ¿te ayudo?"},{"speaker":"B","text":"Sí, ¿me puedo probar esto? ¿Qué talla es?"},{"speaker":"A","text":"Es una mediana. Los probadores están allí."},{"speaker":"B","text":"Gracias. La verdad es que no me queda bien. ¿Lo puedo cambiar por una grande?"},{"speaker":"A","text":"Claro. ¿Tienes el ticket?"}],"practicePhrases":["¿Me puedo probar esto?","¿Lo tienes en una talla más pequeña?","Quería devolver esto.","¿Esto está en oferta?"]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"You're in a clothes shop. Ask about a size, say you want to try it on, and that you want to return something."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('the-weather', 'The Weather', 'Habla del tiempo y del pronóstico en inglés.', 'EN', 'INTERMEDIATE', 26, 'the-weather', $topic${"sections":[{"title":"El tiempo","intro":"La conversación más común que existe: describe el día de hoy y lee un pronóstico.","vocabulary":[{"term":"it's sunny","translation":"hace sol"},{"term":"it's raining","translation":"está lloviendo"},{"term":"it's cold / hot","translation":"hace frío / calor"},{"term":"cloudy","translation":"nublado"},{"term":"windy","translation":"hace viento"},{"term":"forecast","translation":"pronóstico"},{"term":"to snow","translation":"nevar"},{"term":"umbrella","translation":"paraguas"}],"dialogue":[{"speaker":"A","text":"What's the weather like today?"},{"speaker":"B","text":"It's cloudy and a bit cold. Take a jacket."},{"speaker":"A","text":"Is it going to rain?"},{"speaker":"B","text":"The forecast says yes, this afternoon. Bring an umbrella."},{"speaker":"A","text":"Okay, thanks. I hope it's sunny tomorrow."}],"practicePhrases":["What's the weather like?","It's really hot today.","Do I need an umbrella?","It's going to rain."]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Describe el tiempo que hace hoy y el que crees que hará mañana. Di qué ropa te vas a poner."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('el-tiempo', 'El tiempo', 'Talk about the weather and the forecast in Spanish.', 'ES', 'INTERMEDIATE', 26, 'the-weather', $topic${"sections":[{"title":"The weather","intro":"The most common small talk there is — describe today and read a forecast.","vocabulary":[{"term":"hace sol","translation":"it's sunny"},{"term":"está lloviendo","translation":"it's raining"},{"term":"hace frío / calor","translation":"it's cold / hot"},{"term":"nublado","translation":"cloudy"},{"term":"hace viento","translation":"windy"},{"term":"el pronóstico","translation":"forecast"},{"term":"nevar","translation":"to snow"},{"term":"el paraguas","translation":"umbrella"}],"dialogue":[{"speaker":"A","text":"¿Qué tiempo hace hoy?"},{"speaker":"B","text":"Está nublado y hace un poco de frío. Coge una chaqueta."},{"speaker":"A","text":"¿Va a llover?"},{"speaker":"B","text":"El pronóstico dice que sí, esta tarde. Lleva un paraguas."},{"speaker":"A","text":"Vale, gracias. Espero que mañana haga sol."}],"practicePhrases":["¿Qué tiempo hace?","Hoy hace mucho calor.","¿Necesito paraguas?","Va a llover."]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Describe today's weather and what you think it'll be like tomorrow. Say what you're going to wear."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('getting-around', 'Getting Around the City', 'Usa el transporte público y pregunta rutas en inglés.', 'EN', 'INTERMEDIATE', 27, 'getting-around', $topic${"sections":[{"title":"Por la ciudad","intro":"Autobuses, trenes y billetes: cómo preguntar una ruta y llegar a tu destino.","vocabulary":[{"term":"bus / train / subway","translation":"autobús / tren / metro"},{"term":"ticket","translation":"billete / boleto"},{"term":"stop / station","translation":"parada / estación"},{"term":"to take (transport)","translation":"coger / tomar"},{"term":"How do I get to…?","translation":"¿cómo llego a…?"},{"term":"on foot / to walk","translation":"a pie / andar"},{"term":"taxi","translation":"taxi"},{"term":"map","translation":"mapa"}],"dialogue":[{"speaker":"A","text":"Excuse me, how do I get to the museum?"},{"speaker":"B","text":"Take the number 5 bus. It's about ten minutes."},{"speaker":"A","text":"Where's the stop?"},{"speaker":"B","text":"Just around the corner. Or you can walk, it's not far."},{"speaker":"A","text":"I'll take the bus. Where can I buy a ticket?"}],"practicePhrases":["How do I get to the center?","Where's the nearest station?","Which bus goes downtown?","Is it far on foot?"]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"Estás perdido en una ciudad. Pregunta cómo llegar a un sitio y qué transporte tomar."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('por-la-ciudad', 'Por la ciudad', 'Use public transport and ask for routes in Spanish.', 'ES', 'INTERMEDIATE', 27, 'getting-around', $topic${"sections":[{"title":"Around the city","intro":"Buses, trains and tickets — how to ask for a route and get to where you’re going.","vocabulary":[{"term":"el autobús / el tren / el metro","translation":"bus / train / subway"},{"term":"el billete / el boleto","translation":"ticket"},{"term":"la parada / la estación","translation":"stop / station"},{"term":"coger / tomar","translation":"to take (transport)"},{"term":"¿cómo llego a…?","translation":"How do I get to…?"},{"term":"a pie / andar","translation":"on foot / to walk"},{"term":"el taxi","translation":"taxi"},{"term":"el mapa","translation":"map"}],"dialogue":[{"speaker":"A","text":"Perdona, ¿cómo llego al museo?"},{"speaker":"B","text":"Coge el autobús número 5. Son unos diez minutos."},{"speaker":"A","text":"¿Dónde está la parada?"},{"speaker":"B","text":"A la vuelta de la esquina. O puedes ir andando, no está lejos."},{"speaker":"A","text":"Cojo el autobús. ¿Dónde compro un billete?"}],"practicePhrases":["¿Cómo llego al centro?","¿Dónde está la estación más cercana?","¿Qué autobús va al centro?","¿Está lejos a pie?"]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"You are lost in a city. Ask how to get somewhere and what transport to take."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('job-interview-basics', 'Job Interview Basics', 'Habla de tu experiencia, responde preguntas comunes y haz preguntas inteligentes, en inglés.', 'EN', 'ADVANCED', 40, 'job-interview', $topic${"sections":[{"title":"Hablar de tu experiencia","intro":"En una entrevista te pedirán que cuentes tu trayectoria. Sé conciso y relevante.","vocabulary":[{"term":"I've been working as...","translation":"He estado trabajando como..."},{"term":"I led a team of...","translation":"Lideré un equipo de..."},{"term":"I'm responsible for...","translation":"Soy responsable de..."},{"term":"I specialise in...","translation":"Me especializo en..."}],"dialogue":[{"speaker":"Interviewer","text":"Tell me a bit about yourself."},{"speaker":"You","text":"Sure. I've been working as a backend engineer for five years, mostly with Node.js and Postgres. At my current company, I lead a team of three."},{"speaker":"Interviewer","text":"What kind of projects?"},{"speaker":"You","text":"Mostly real-time systems — chat, notifications, that kind of thing."}],"practicePhrases":["I've been working as a [role] for [number] years.","I specialise in [field].","I'm currently responsible for [task]."]},{"title":"Shadowing del diálogo","intro":"Escucha y repite el diálogo del tema en voz alta. La repetición fija la pronunciación y el ritmo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Pon en práctica","intro":"Graba tu respuesta usando lo que aprendiste. La IA te dará feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"El entrevistador te dice: 'Tell me a bit about yourself.' Cuenta tu rol, años de experiencia, especialidad y un proyecto reciente."},{"title":"Conectar","intro":"Practica este tema con otro usuario en vivo.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb),
  ('entrevista-de-trabajo', 'Entrevista de trabajo', 'Talk about your experience, answer common questions, and ask good ones in Spanish.', 'ES', 'ADVANCED', 40, 'job-interview', $topic${"sections":[{"title":"Talking about your experience","intro":"Interviewers will ask you to walk them through your background. Keep it concise and relevant.","vocabulary":[{"term":"He trabajado como...","translation":"I've worked as..."},{"term":"Dirigí un equipo de...","translation":"I led a team of..."},{"term":"Soy responsable de...","translation":"I'm responsible for..."},{"term":"Me especializo en...","translation":"I specialise in..."}],"dialogue":[{"speaker":"Entrevistador","text":"Cuéntame un poco sobre ti."},{"speaker":"Tú","text":"Claro. He trabajado como ingeniero de backend durante cinco años, sobre todo con Node.js y Postgres. En mi empresa actual dirijo un equipo de tres."},{"speaker":"Entrevistador","text":"¿Qué tipo de proyectos?"},{"speaker":"Tú","text":"Sobre todo sistemas en tiempo real: chat, notificaciones, ese tipo de cosas."}],"practicePhrases":["He trabajado como [puesto] durante [número] años.","Me especializo en [campo].","Ahora mismo soy responsable de [tarea]."]},{"title":"Shadow the dialogue","intro":"Listen and repeat the dialogue out loud. Repetition locks in your pronunciation and rhythm.","vocabulary":[],"dialogue":[],"practicePhrases":[],"shadowing":true},{"title":"Put it into practice","intro":"Record your answer using what you learned. The AI will give you feedback.","vocabulary":[],"dialogue":[],"practicePhrases":[],"freeRecordingPrompt":"The interviewer says: 'Tell me a bit about yourself.' Talk about your role, years of experience, specialty, and a recent project."},{"title":"Connect","intro":"Practice this topic live with another person.","vocabulary":[],"dialogue":[],"practicePhrases":[],"comingSoon":"tandem"}]}$topic$::jsonb)
